);


--
-- Name: alertas; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alertas (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tipo public."TipoAlerta" NOT NULL,
    titulo character varying(255) NOT NULL,
    descripcion text NOT NULL,
    nivel public."NivelAlerta" NOT NULL,
    fecha_creacion timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_vencimiento timestamp(6) with time zone,
    leida boolean DEFAULT false NOT NULL,
    usuario_id uuid,
    parametros jsonb,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


